package com.thangit.boardinghouse.service;

import static com.thangit.boardinghouse.service.MonthlyBillingService.*;
import com.thangit.boardinghouse.domain.auth.RoleCode;
import com.thangit.boardinghouse.security.AuthenticatedUser;
import com.thangit.boardinghouse.dto.request.lifecycle.RentalLifecycleRequests.*;
import com.thangit.boardinghouse.service.impl.RentalLifecycleServiceImpl;
import jakarta.validation.constraints.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Agreements coordinate existing handover, onboarding and ledger workflows; never rewrite a signer. */
@Service
public class ContractChangeService {
    public record Request(@NotBlank @Pattern(regexp="EXTENSION|TRANSFER|REPRESENTATIVE") String type,
        @NotNull LocalDate effectiveDate,@NotNull LocalDate newEndDate,
        @NotNull @DecimalMin("0") @Digits(integer=13,fraction=2) BigDecimal monthlyRent,
        @NotNull @DecimalMin("0") @Digits(integer=13,fraction=2) BigDecimal depositRequired,
        @NotBlank @Pattern(regexp="FULL_MONTH|ACTUAL_DAYS") String proration,
        @Positive Long targetRoomId,@Positive Long targetProfileId,@NotBlank @Size(max=500) String reference,
        @NotBlank @Size(max=1000) String reason) {}
    public record Action(@com.fasterxml.jackson.annotation.JsonProperty(required=true) @Min(0) long version,@NotBlank @Size(max=1000) String reason) {}
    public record Confirm(@com.fasterxml.jackson.annotation.JsonProperty(required=true) @Min(0) long version,@NotBlank @Pattern(regexp="[a-f0-9]{64}") String hash) {}
    public record MoveDeposit(@com.fasterxml.jackson.annotation.JsonProperty(required=true) @Min(0) long version,@NotNull @DecimalMin("0.01") @Digits(integer=13,fraction=2) BigDecimal amount,
        @NotBlank @Size(max=100) String key,@NotBlank @Size(max=1000) String reason) {}
    private void cancelPrepared(AuthenticatedUser p,Map<String,Object> q,String reason){
        if(q.get("checkout_id")!=null){var co=rows("SELECT * FROM rental_checkouts WHERE id=:id",id(q,"checkout_id")).getFirst();if(co.get("actual_checkout_at")!=null)throw fail("TRANSFER_ALREADY_HANDED_OVER","Đã bàn giao thực tế; cần quy trình chuyển ngược có chứng từ.");checkout.cancel(p,id(co,"id"),new CheckoutSettlementService.VersionedReason(id(co,"version"),reason));}
        if(q.get("target_booking_id")!=null){var held=ledger.byBooking(id(q,"target_booking_id"));if(money(held.get("balance_amount")).signum()>0||!rows("SELECT id FROM deposit_transactions WHERE deposit_id=:id",id(held,"id")).isEmpty())throw fail("TRANSFER_CANCELLATION_RECONCILIATION_REQUIRED","Booking đích đã có giao dịch cọc; cần đối soát trước hủy.");}
        if(q.get("target_contract_id")==null){if(q.get("target_booking_id")!=null){long room=id(q,"target_room_id");var dest=rooms.lockRoom(room);if(p.activeRole()!=RoleCode.TENANT)rooms.access(p,id(dest,"property_id"));db.sql("UPDATE rental_bookings SET status='CANCELLED',version=version+1 WHERE id=:id AND status='RESERVED'").param("id",q.get("target_booking_id")).update();new com.thangit.boardinghouse.repository.RentalLifecycleRepository(db,rooms).history(id(q,"target_booking_id"),"RESERVED","CANCELLED",reason,p.id());rooms.release(room,reason,p.id());}return;}
        // A prepared target can only be cancelled while it has no financial or handover postings.
        var c=contract(id(q,"target_contract_id"));access(p,c,false);var d=ledger.byContract(id(c,"id"));
        if(!"PENDING_CONFIRMATION".equals(c.get("status"))||money(d.get("balance_amount")).signum()>0||!rows("SELECT id FROM deposit_transactions WHERE deposit_id=:id",id(d,"id")).isEmpty()||!rows("SELECT id FROM invoices WHERE contract_id=:id AND status<>'CANCELLED'",id(c,"id")).isEmpty())throw fail("TRANSFER_CANCELLATION_RECONCILIATION_REQUIRED","Đích đã có chứng từ tài chính/nhận phòng; cần đối soát trước hủy.");
        db.sql("UPDATE contracts SET status='CANCELLED' WHERE id=:id").param("id",c.get("id")).update();db.sql("UPDATE rental_bookings SET status='CANCELLED',version=version+1 WHERE id=:id").param("id",q.get("target_booking_id")).update();rooms.release(id(c,"room_id"),reason,p.id());history(id(c,"id"),p,"TRANSFER_CANCELLED",reason);
    }
    @Transactional public List<Map<String,Object>> invitations(AuthenticatedUser p){if(p==null||p.activeRole()!=RoleCode.TENANT)throw denied("Chỉ người thuê xem lời mời của mình.");return db.sql("SELECT q.id,q.change_type,q.status,q.effective_date FROM contract_change_requests q JOIN tenant_profiles tp ON tp.id=q.target_profile_id WHERE tp.user_id=:id AND q.change_type='REPRESENTATIVE' AND q.status IN ('REQUESTED','OFFERED','AGREED','PREPARED') ORDER BY q.id DESC").param("id",p.id()).query().listOfRows();}
    private String agreementContent(Map<String,Object> q,Map<String,Object> c){
        var signer=rows("SELECT full_name FROM tenant_profiles WHERE id=:id",id(c,"tenant_profile_id")).getFirst();
        long targetRoom=q.get("target_room_id")==null?id(c,"room_id"):id(q,"target_room_id");
        var target=rows("SELECT r.code,p.name FROM rooms r JOIN properties p ON p.id=r.property_id WHERE r.id=:id",targetRoom).getFirst();
        var person=rows("SELECT full_name FROM tenant_profiles WHERE id=:id",id(q,"target_profile_id")).getFirst();
        String kind=switch(q.get("change_type").toString()){case "EXTENSION"->"GIA HẠN";case "TRANSFER"->"CHUYỂN PHÒNG";default->"THAY ĐẠI DIỆN BẰNG HỢP ĐỒNG THAY THẾ";};
        var text=new StringBuilder("THỎA THUẬN ").append(kind).append(" #").append(q.get("id"))
            .append("\nHợp đồng nguồn: ").append(c.get("code")).append("; người ký: ").append(signer.get("full_name"))
            .append("\nHết hạn hiện tại: ").append(c.get("end_date")).append("; ngày hiệu lực mới: ").append(q.get("effective_date"))
            .append("; kết thúc mới: ").append(q.get("new_end_date")).append(" (không bao gồm ngày kết thúc).")
            .append("\nGiá thuê: ").append(q.get("monthly_rent")).append(" VNĐ/tháng; chính sách: ").append("ACTUAL_DAYS".equals(q.get("rent_proration"))?"theo ngày thực tế":"trọn tháng")
            .append("; cọc yêu cầu: ").append(q.get("deposit_required")).append(" VNĐ, không phải tiền đã thu.")
            .append("\nPhòng: ").append(target.get("code")).append(" — ").append(target.get("name")).append("; người thuê: ").append(person.get("full_name"))
            .append("\nCăn cứ: ").append(q.get("evidence_reference")).append("; điều khoản/lý do: ").append(q.get("reason"));
        if(!"EXTENSION".equals(q.get("change_type"))){
            text.append("\nĐiện nước phòng mới theo các đơn giá đã thỏa thuận sau, chỉ số đầu được ghi riêng khi nhận phòng:");
            for(var rate:rows("SELECT code,name,calculation_method,unit_price,unit FROM contract_utility_rates WHERE contract_id=:id ORDER BY code",id(c,"id")))
                text.append("\n- ").append(rate.get("name")).append(": ").append("METER".equals(rate.get("calculation_method"))?"theo công tơ":"cố định").append(", ").append(rate.get("unit_price")).append(" VNĐ/").append(rate.get("unit"));
            text.append("\nDịch vụ và cư dân đi cùng tại phòng mới cần hồ sơ xác minh/thỏa thuận riêng.")
                .append("\nCông nợ và cọc cũ thuộc hợp đồng cũ. Chỉ chuyển cọc thực có sau quyết toán trong cùng người thuê và chủ sở hữu; không chuyển công nợ.")
                .append("\nChuyển toàn bộ cọc thực còn giữ sau quyết toán, tối đa bằng cọc phòng mới còn thiếu; phần dư hoàn riêng. Tiền thuê phòng cũ giữ chính sách đã ký: ").append("ACTUAL_DAYS".equals(c.get("rent_proration"))?"theo ngày thực tế":"trọn tháng; nghĩa vụ trọn tháng không tự giảm khi chuyển phòng")
                .append("\nThay đại diện cần xác nhận người cũ và mới; cọc người cũ hoàn riêng, người mới thu riêng. Thỏa thuận này chưa thay thế biên bản bàn giao hoặc xác nhận nhận phòng.");
        }
        return text.toString();
    }
    private com.thangit.boardinghouse.common.exception.AuthException denied(String message){return new com.thangit.boardinghouse.common.exception.AuthException(org.springframework.http.HttpStatus.FORBIDDEN,"CHANGE_ACCESS_DENIED",message);}
    @Transactional public long legacyRequest(AuthenticatedUser p,long c,long legacy,String reason){rooms.lockContract(c);var contract=contract(c);access(p,contract,false);var er=db.sql("SELECT * FROM contract_extension_requests WHERE id=:id AND contract_id=:c AND status='PENDING' FOR UPDATE").param("id",legacy).param("c",c).query().singleRow();LocalDate effective=date(contract.get("end_date")).isBefore(LocalDate.now())?LocalDate.now():date(contract.get("end_date"));long q=request(p,c,new Request("EXTENSION",effective,date(er.get("requested_end_date")),new MonthlyBillingService(db).price(c,"RENT",effective,money(contract.get("agreed_monthly_rent"))),money(contract.get("deposit_amount")),contract.get("rent_proration").toString(),null,null,"Yêu cầu gia hạn #"+legacy,reason));db.sql("UPDATE contract_change_requests SET legacy_extension_id=:legacy WHERE id=:id").param("id",q).param("legacy",legacy).update();return q;}
    private String sourceFingerprint(Map<String,Object> c){return hash(c.get("id")+"|"+c.get("tenant_id")+"|"+c.get("tenant_profile_id")+"|"+c.get("room_id")+"|"+c.get("end_date")+"|"+rows("SELECT code,calculation_method,unit_price,unit FROM contract_utility_rates WHERE contract_id=:id ORDER BY code",id(c,"id")));}
    @SuppressWarnings("unchecked") private Map<String,Object> invitationView(AuthenticatedUser p,Map<String,Object> c,Map<String,Object> out){if(p.activeRole()==RoleCode.TENANT&&p.id()!=id(c,"tenant_id")){var limited=new LinkedHashMap<String,Object>();for(String key:List.of("code","end_date","original_end_date"))limited.put(key,c.get(key));out.put("contract",limited);out.put("rooms",List.of());out.put("prices",List.of());out.put("residents",((List<Map<String,Object>>)out.get("residents")).stream().filter(r->(r.get("user_id") instanceof Number u&&u.longValue()==p.id())||id(r,"tenant_profile_id")==id(c,"tenant_profile_id")).toList());}return out;}
    private final JdbcClient db;
    private final RoomLifecycleGuard rooms;
    private final RentalLifecycleServiceImpl lifecycle;
    private final DepositLedgerService ledger;
    private final ContractOnboardingService onboarding;
    private final CheckoutSettlementService checkout;
    public ContractChangeService(JdbcClient db,RoomLifecycleGuard rooms,RentalLifecycleServiceImpl lifecycle,
        DepositLedgerService ledger,ContractOnboardingService onboarding,CheckoutSettlementService checkout){this.checkout=checkout;this.db=db;this.rooms=rooms;this.lifecycle=lifecycle;this.ledger=ledger;this.onboarding=onboarding;}
    private List<Map<String,Object>> rows(String sql,long id){return db.sql(sql).param("id",id).query().listOfRows();}
    private Map<String,Object> contract(long id){return rows("SELECT c.*,r.property_id,p.owner_id FROM contracts c JOIN rooms r ON r.id=c.room_id JOIN properties p ON p.id=r.property_id WHERE c.id=:id FOR UPDATE",id).stream().findFirst().orElseThrow(()->fail("CONTRACT_NOT_FOUND","Không tìm thấy hợp đồng."));}
    private void access(AuthenticatedUser p,Map<String,Object> c,boolean staff){
        if(p==null)throw denied("Không có quyền.");
        if(staff&&p.activeRole()==RoleCode.MANAGER)rooms.capability(p,id(c,"property_id"),com.thangit.boardinghouse.security.PropertyAuthorization.Capability.CONTRACT_APPROVE);
        if(Set.of(RoleCode.OWNER,RoleCode.MANAGER).contains(p.activeRole()))rooms.access(p,id(c,"property_id"));
        else if(staff||p.activeRole()!=RoleCode.TENANT||p.id()!=id(c,"tenant_id"))throw denied("Không có quyền thay đổi hợp đồng này.");
    }
    private Map<String,Object> change(AuthenticatedUser p,long request,boolean staff){
        long cid=db.sql("SELECT contract_id FROM contract_change_requests WHERE id=:id").param("id",request).query(Long.class).optional().orElseThrow(()->fail("CHANGE_NOT_FOUND","Không tìm thấy yêu cầu."));
        rooms.lockContract(cid);var c=contract(cid);var q=rows("SELECT * FROM contract_change_requests WHERE id=:id FOR UPDATE",request).getFirst();
        boolean newParty=!staff&&p!=null&&p.activeRole()==RoleCode.TENANT&&"REPRESENTATIVE".equals(q.get("change_type"))&&Objects.equals(p.id(),profileUser(q.get("target_profile_id")));
        if(!newParty)access(p,c,staff);return q;
    }
    private Long profileUser(Object profile){return profile==null?null:db.sql("SELECT user_id FROM tenant_profiles WHERE id=:id").param("id",profile).query(Long.class).optional().orElse(null);}
    private void expected(Map<String,Object> q,long v){if(id(q,"version")!=v)throw fail("CHANGE_VERSION_CONFLICT","Hồ sơ đã thay đổi; tải lại trước khi thao tác.");}
    private void state(Map<String,Object> q,String... states){if(!Set.of(states).contains(q.get("status")))throw fail("CHANGE_STATE_INVALID","Trạng thái không cho phép thao tác này.");}
    private void live(Map<String,Object> c){if(!Set.of("ACTIVE","EXPIRING","EXPIRED").contains(c.get("status"))||c.get("operational_ended_at")!=null)throw fail("CHANGE_CONTRACT_INVALID","Hợp đồng đã kết thúc hoặc chưa đủ điều kiện thay đổi.");if(!rows("SELECT id FROM rental_checkouts WHERE contract_id=:id AND status<>'CANCELLED'",id(c,"id")).isEmpty())throw fail("CHECKOUT_ALREADY_REQUESTED","Cần giải quyết yêu cầu trả phòng trước.");}
    private void audit(long q,AuthenticatedUser p,String event,String content){db.sql("INSERT INTO contract_change_history(request_id,event_type,content,actor_id) VALUES(:id,:event,:content,:actor)").param("id",q).param("event",event).param("content",content).param("actor",p.id()).update();}
    private void history(long c,AuthenticatedUser p,String event,String note){db.sql("INSERT INTO contract_history(contract_id,event_type,description,actor_name,note) VALUES(:id,:event,:description,:actor,:note)").param("id",c).param("event",event).param("description",event).param("actor",p.email()).param("note",note.substring(0,Math.min(500,note.length()))).update();}
    private Request terms(Map<String,Object> q){return new Request(q.get("change_type").toString(),date(q.get("effective_date")),date(q.get("new_end_date")),money(q.get("monthly_rent")),money(q.get("deposit_required")),q.get("rent_proration").toString(),q.get("target_room_id")==null?null:id(q,"target_room_id"),q.get("target_profile_id")==null?null:id(q,"target_profile_id"),q.get("evidence_reference").toString(),q.get("reason").toString());}
    private void validate(Map<String,Object> c,Request r,AuthenticatedUser approver){
        if(r.effectiveDate().isBefore(LocalDate.now())||!r.newEndDate().isAfter(r.effectiveDate()))throw fail("CHANGE_DATES_INVALID","Ngày hiệu lực/kết thúc không hợp lệ; không sửa giá hồi tố.");
        if("EXTENSION".equals(r.type())){
            if("FULL_MONTH".equals(r.proration())&&r.effectiveDate().getDayOfMonth()!=1&&r.monthlyRent().compareTo(new MonthlyBillingService(db).price(id(c,"id"),"RENT",r.effectiveDate(),money(c.get("agreed_monthly_rent"))))!=0)throw fail("RENT_PRORATION_AGREEMENT_REQUIRED","Mid-month price change requires an agreed ACTUAL_DAYS policy");
            if(!r.newEndDate().isAfter(date(c.get("end_date")))||r.effectiveDate().isBefore(date(c.get("end_date"))))throw fail("EXTENSION_DATE_INVALID","Gia hạn phải nối từ ngày kết thúc hiện tại, không sửa thời hạn đã ký.");
            if(r.effectiveDate().isAfter(date(c.get("end_date")))&&!date(c.get("end_date")).isBefore(LocalDate.now()))throw fail("EXTENSION_GAP_INVALID","Gia hạn đang hiệu lực phải nối liên tục; hợp đồng hết hạn cần ghi rõ thời điểm khôi phục.");
            if(money(c.get("deposit_amount")).compareTo(r.depositRequired())!=0||!Objects.equals(c.get("rent_proration"),r.proration()))throw fail("EXTENSION_TERMS_INVALID","Không tự đổi cọc hoặc chính sách phân bổ qua gia hạn.");
            Long booking=db.sql("SELECT id FROM rental_bookings WHERE contract_id=:id").param("id",c.get("id")).query(Long.class).optional().orElse(null);
            rooms.contractDates(id(c,"room_id"),date(c.get("start_date")),r.newEndDate(),id(c,"id"),booking);
            if(!rows("SELECT id FROM billing_rate_versions WHERE contract_id=:id AND code='RENT' AND effective_date>='"+r.effectiveDate()+"'",id(c,"id")).isEmpty())throw fail("RENT_AMENDMENT_CONFLICT","Có giá đã cam kết trong khoảng gia hạn; cần đối soát.");
            if(!rows("SELECT id FROM invoices WHERE contract_id=:id AND billing_period>='"+r.effectiveDate().withDayOfMonth(1)+"' AND status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED')",id(c,"id")).isEmpty())throw fail("AMENDMENT_ALREADY_BILLED","Kỳ chịu ảnh hưởng đã lập hóa đơn; phải điều chỉnh có chứng từ.");
        }else{
            long target="REPRESENTATIVE".equals(r.type())?id(c,"room_id"):Objects.requireNonNullElse(r.targetRoomId(),0L);
            if(target==0||("TRANSFER".equals(r.type())&&target==id(c,"room_id")))throw fail("TRANSFER_ROOM_INVALID","Phòng đích phải khác phòng hiện tại.");
            var dest=rooms.lockRoom(target);long owner=db.sql("SELECT owner_id FROM properties WHERE id=:id").param("id",dest.get("property_id")).query(Long.class).single();
            if(owner!=id(c,"owner_id"))throw fail("TRANSFER_OWNER_MISMATCH","Khác chủ sở hữu: cần hoàn/thu mới theo hồ sơ riêng, không tự điều chuyển.");
            if("TRANSFER".equals(r.type()))rooms.availableForBooking(target);
            if("REPRESENTATIVE".equals(r.type())){
                if(r.targetProfileId()==null||r.targetProfileId()==id(c,"tenant_profile_id")||profileUser(r.targetProfileId())==null)throw fail("REPRESENTATIVE_INVALID","Cần người đại diện mới đã có tài khoản xác minh.");
                if(db.sql("SELECT COUNT(*) FROM tenant_residences WHERE tenant_profile_id=:profile AND contract_id=:id AND status='ACTIVE' AND residence_role<>'REPRESENTATIVE'").param("profile",r.targetProfileId()).param("id",c.get("id")).query(Long.class).single()!=1)throw fail("REPRESENTATIVE_INVALID","Người đại diện mới phải có cư trú hợp lệ trong hợp đồng.");
            }
            if(approver!=null)rooms.access(approver,id(dest,"property_id"));
        }
    }
    private void validateStaff(AuthenticatedUser p,Map<String,Object> c,Request r){validate(c,r,p);}
    @Transactional public long request(AuthenticatedUser p,long c,Request r){rooms.lockContract(c);var contract=contract(c);access(p,contract,false);live(contract);
        if(!rows("SELECT id FROM contract_change_requests WHERE contract_id=:id AND active_contract_id IS NOT NULL FOR UPDATE",c).isEmpty())throw fail("CHANGE_ALREADY_PENDING","Hợp đồng đã có hồ sơ thay đổi đang xử lý.");
        validate(contract,r,p.activeRole()==RoleCode.TENANT?null:p);var kh=new GeneratedKeyHolder();db.sql("INSERT INTO contract_change_requests(contract_id,change_type,old_end_date,effective_date,new_end_date,monthly_rent,deposit_required,rent_proration,target_room_id,target_profile_id,evidence_reference,reason,requested_by) VALUES(:id,:type,:old,:effective,:end,:rent,:deposit,:policy,:room,:profile,:ref,:reason,:actor)").param("id",c).param("type",r.type()).param("old",contract.get("end_date")).param("effective",r.effectiveDate()).param("end",r.newEndDate()).param("rent",r.monthlyRent()).param("deposit",r.depositRequired()).param("policy",r.proration()).param("room","REPRESENTATIVE".equals(r.type())?contract.get("room_id"):r.targetRoomId()).param("profile","REPRESENTATIVE".equals(r.type())?r.targetProfileId():contract.get("tenant_profile_id")).param("ref",r.reference()).param("reason",r.reason()).param("actor",p.id()).update(kh,"id");long id=kh.getKey().longValue();audit(id,p,"REQUESTED",r.toString());return id;
    }
    @Transactional public void offer(AuthenticatedUser p,long id,Action r){var q=change(p,id,true);expected(q,r.version());state(q,"REQUESTED");var c=contract(id(q,"contract_id"));live(c);validateStaff(p,c,terms(q));
        if("TRANSFER".equals(q.get("change_type"))){var hold=lifecycle.createBooking(p,new CreateBooking(id(q,"target_profile_id"),id(q,"target_room_id"),LocalDate.now(),date(q.get("new_end_date")),BigDecimal.ZERO,"CONTRACT_CHANGE","Agreement #"+id));db.sql("UPDATE contract_change_requests SET target_booking_id=:booking WHERE id=:id").param("id",id).param("booking",hold.id()).update();}
        String content=agreementContent(q,c);
        db.sql("UPDATE contract_change_requests SET status='OFFERED',version=version+1,content=:content,content_hash=:hash,source_hash=:source WHERE id=:id").param("id",id).param("content",content).param("hash",hash(content)).param("source",sourceFingerprint(c)).update();q=change(p,id,true);sign(q,p,"LANDLORD");audit(id,p,"OFFERED",content+"; "+r.reason());
    }
    private void sign(Map<String,Object> q,AuthenticatedUser p,String party){db.sql("INSERT IGNORE INTO contract_change_confirmations(request_id,version,party,content_hash,actor_id) VALUES(:id,:version,:party,:hash,:actor)").param("id",q.get("id")).param("version",q.get("version")).param("party",party).param("hash",q.get("content_hash")).param("actor",p.id()).update();}
    private boolean signed(Map<String,Object> q,String party){return db.sql("SELECT COUNT(*) FROM contract_change_confirmations WHERE request_id=:id AND version=:version AND party=:party AND content_hash=:hash FOR UPDATE").param("id",q.get("id")).param("version",q.get("version")).param("party",party).param("hash",q.get("content_hash")).query(Long.class).single()==1;}
    @Transactional public void confirm(AuthenticatedUser p,long id,Confirm r){var q=change(p,id,false);state(q,"OFFERED");expected(q,r.version());if(!Objects.equals(q.get("content_hash"),r.hash())||p.activeRole()!=RoleCode.TENANT)throw fail("CHANGE_CONFIRMATION_INVALID","Cần xác nhận đúng nội dung bằng tài khoản của bên liên quan.");var c=contract(id(q,"contract_id"));String party=p.id()==id(c,"tenant_id")?"OLD_TENANT":"NEW_TENANT";sign(q,p,party);audit(id,p,"CONFIRMED",party+"; "+r.hash());if(signed(q,"OLD_TENANT")&&(!"REPRESENTATIVE".equals(q.get("change_type"))||signed(q,"NEW_TENANT")))db.sql("UPDATE contract_change_requests SET status='AGREED' WHERE id=:id").param("id",id).update();}
    @Transactional public void applyExtension(AuthenticatedUser p,long id,Action r){var q=change(p,id,true);expected(q,r.version());state(q,"AGREED");if(!"EXTENSION".equals(q.get("change_type")))throw fail("CHANGE_TYPE_INVALID","Đây không phải hồ sơ gia hạn.");var c=contract(id(q,"contract_id"));live(c);if(!Objects.equals(date(c.get("end_date")),date(q.get("old_end_date"))))throw fail("CHANGE_SOURCE_CHANGED","Thời hạn nguồn đã thay đổi; cần hồ sơ mới.");validateStaff(p,c,terms(q));
        db.sql("INSERT INTO billing_rate_versions(contract_id,code,effective_date,unit_price,reference,reason,actor_id) VALUES(:id,'RENT',:date,:price,:ref,:reason,:actor)").param("id",c.get("id")).param("date",q.get("effective_date")).param("price",q.get("monthly_rent")).param("ref",q.get("evidence_reference")).param("reason","Phụ lục #"+id+": "+r.reason()).param("actor",p.id()).update();
        db.sql("UPDATE contracts SET end_date=:end,status='ACTIVE' WHERE id=:id").param("id",c.get("id")).param("end",q.get("new_end_date")).update();db.sql("UPDATE contract_change_requests SET status='COMPLETED',version=version+1 WHERE id=:id").param("id",id).update();if(q.get("legacy_extension_id")!=null)db.sql("UPDATE contract_extension_requests SET status='APPROVED',reviewed_at=NOW(),reviewed_by=:actor,review_reason=:reason WHERE id=:id").param("id",q.get("legacy_extension_id")).param("actor",p.id()).param("reason",r.reason()).update();history(id(c,"id"),p,"EXTENSION_APPLIED",q.get("content").toString());onboarding.recordVersion(id(c,"id"),p.id(),r.reason());audit(id,p,"EXTENSION_APPLIED",r.reason());
    }
    @Transactional public long legacyOffer(AuthenticatedUser p,long c,long legacy,String reason){rooms.lockContract(c);var contract=contract(c);access(p,contract,true);var er=db.sql("SELECT * FROM contract_extension_requests WHERE id=:id AND contract_id=:c FOR UPDATE").param("id",legacy).param("c",c).query().singleRow();if(!"PENDING".equals(er.get("status")))throw fail("EXTENSION_ALREADY_REVIEWED","Extension request is already processed");var existing=rows("SELECT id FROM contract_change_requests WHERE legacy_extension_id=:id",legacy);if(!existing.isEmpty()){long q=id(existing.getFirst(),"id");var saved=change(p,q,true);if("REQUESTED".equals(saved.get("status")))offer(p,q,new Action(id(saved,"version"),reason));return q;}LocalDate effective=date(contract.get("end_date")).isBefore(LocalDate.now())?LocalDate.now():date(contract.get("end_date"));long q=request(p,c,new Request("EXTENSION",effective,date(er.get("requested_end_date")),new MonthlyBillingService(db).price(c,"RENT",effective,money(contract.get("agreed_monthly_rent"))),money(contract.get("deposit_amount")),contract.get("rent_proration").toString(),null,null,"Legacy extension #"+legacy,reason));db.sql("UPDATE contract_change_requests SET legacy_extension_id=:legacy WHERE id=:id").param("legacy",legacy).param("id",q).update();offer(p,q,new Action(0,reason));return q;}
    @Transactional public void cancel(AuthenticatedUser p,long id,Action r){var q=change(p,id,false);expected(q,r.version());state(q,"REQUESTED","OFFERED","AGREED","PREPARED");cancelPrepared(p,q,r.reason());db.sql("UPDATE contract_change_requests SET status='CANCELLED',version=version+1 WHERE id=:id").param("id",id).update();if(q.get("legacy_extension_id")!=null)db.sql("UPDATE contract_extension_requests SET status='CANCELLED' WHERE id=:id").param("id",q.get("legacy_extension_id")).update();audit(id,p,"CANCELLED",r.reason());}
    @Transactional public void prepareMove(AuthenticatedUser p,long id,Action r){var q=change(p,id,true);expected(q,r.version());state(q,"AGREED");if("EXTENSION".equals(q.get("change_type")))throw fail("CHANGE_TYPE_INVALID","Hồ sơ gia hạn không chuyển phòng.");var c=contract(id(q,"contract_id"));rooms.access(p,id(c,"property_id"));
        if(!Objects.equals(q.get("source_hash"),sourceFingerprint(c)))throw fail("CHANGE_SOURCE_CHANGED","Source agreement changed; cancel and review a new request");
        // Never change room_id/tenant_id of the signed source contract.
        long checkout;var old=rows("SELECT id FROM rental_checkouts WHERE contract_id=:id AND status<>'CANCELLED'",id(c,"id"));if(old.isEmpty())checkout=lifecycle.requestCheckout(p,new RequestCheckout(id(c,"id"),date(q.get("effective_date")),"Theo thỏa thuận thay đổi #"+id)).id();else checkout=id(old.getFirst(),"id");
        db.sql("UPDATE contract_change_requests SET checkout_id=:checkout WHERE id=:id").param("id",id).param("checkout",checkout).update();
        if("REPRESENTATIVE".equals(q.get("change_type"))){if(rows("SELECT id FROM rental_checkouts WHERE id=:id AND actual_checkout_at IS NOT NULL",checkout).isEmpty()){audit(id,p,"OLD_HANDOVER_REQUIRED",r.reason());return;}}
        long room=id(q,"target_room_id");rooms.lockRoom(room);var dest=rows("SELECT * FROM rooms WHERE id=:id",room).getFirst();rooms.access(p,id(dest,"property_id"));if(q.get("target_booking_id")==null)rooms.availableForBooking(room);
        var booking=q.get("target_booking_id")!=null?new com.thangit.boardinghouse.dto.response.lifecycle.RentalLifecycleResponses.Created(id(q,"target_booking_id"),"",""):lifecycle.createBooking(p,new CreateBooking(id(q,"target_profile_id"),room,LocalDate.now(),date(q.get("new_end_date")),BigDecimal.ZERO,"CONTRACT_CHANGE","Thỏa thuận #"+id));
        var rates=rows("SELECT * FROM contract_utility_rates WHERE contract_id=:id ORDER BY code",id(c,"id")).stream().map(x->new AgreedRate(x.get("code").toString(),x.get("name").toString(),x.get("calculation_method").toString(),money(x.get("unit_price")),x.get("unit").toString())).toList();
        long target=lifecycle.createContract(p,booking.id(),new CreateContract(date(q.get("effective_date")),date(q.get("new_end_date")),money(q.get("deposit_required")),((Number)c.get("payment_due_day")).intValue(),((Number)c.get("notice_period_days")).intValue(),BigDecimal.ZERO,money(q.get("monthly_rent")),rates,null,List.of(new AgreedTerm("Thỏa thuận chuyển đổi",q.get("content").toString())),false)).id();
        db.sql("UPDATE contracts SET rent_proration=:policy WHERE id=:id").param("id",target).param("policy",q.get("rent_proration")).update();db.sql("UPDATE contract_change_requests SET target_booking_id=:booking,target_contract_id=:target,status='PREPARED',version=version+1 WHERE id=:id").param("id",id).param("booking",booking.id()).param("target",target).update();history(target,p,"REPLACEMENT_CREATED","Hợp đồng nguồn #"+c.get("id")+"; thỏa thuận #"+id);audit(id,p,"TARGET_PREPARED","Old checkout="+checkout+"; target contract="+target+"; "+r.reason());
    }
    @Transactional public void transferDeposit(AuthenticatedUser p,long id,MoveDeposit r){var q=change(p,id,true);expected(q,r.version());state(q,"PREPARED");if(!"TRANSFER".equals(q.get("change_type")))throw fail("DEPOSIT_TRANSFER_INVALID","Thay đại diện phải hoàn cọc người cũ và thu người mới; không chuyển nghĩa vụ.");var prior=rows("SELECT * FROM contract_change_deposit_allocations WHERE request_id=:id FOR UPDATE",id);if(!prior.isEmpty()){if(money(prior.getFirst().get("amount")).compareTo(r.amount())!=0||!Objects.equals(prior.getFirst().get("idempotency_key"),r.key())||!Objects.equals(prior.getFirst().get("fingerprint"),hash(r.amount().stripTrailingZeros()+"|"+r.reason())))throw fail("MOVE_DEPOSIT_ALREADY_TRANSFERRED","This agreement has already transferred its deposit allocation");return;}var held=ledger.byContract(id(q,"contract_id"));var targetDeposit=ledger.byContract(id(q,"target_contract_id"));BigDecimal planned=money(held.get("balance_amount")).min(money(targetDeposit.get("required_amount")).subtract(money(targetDeposit.get("balance_amount"))).max(BigDecimal.ZERO));if(r.amount().compareTo(planned)!=0)throw fail("DEPOSIT_TRANSFER_PLAN_CHANGED","Transfer must match the agreed net remainder capped by the target shortfall");var posted=ledger.transferSettledMove(p,id(q,"contract_id"),id(q,"target_contract_id"),r.key(),r.amount(),"Thỏa thuận #"+id+"; "+q.get("content_hash"),r.reason());db.sql("INSERT INTO contract_change_deposit_allocations(request_id,transaction_id,amount,idempotency_key,fingerprint,actor_id) VALUES(:id,:transaction,:amount,:key,:fingerprint,:actor)").param("id",id).param("transaction",posted.get("id")).param("amount",r.amount()).param("key",r.key()).param("fingerprint",hash(r.amount().stripTrailingZeros()+"|"+r.reason())).param("actor",p.id()).update();audit(id,p,"DEPOSIT_TRANSFERRED",r.amount()+"; "+r.reason());}
    @Transactional public void completeMove(AuthenticatedUser p,long id,Action r){var q=change(p,id,true);expected(q,r.version());state(q,"PREPARED");var old=contract(id(q,"contract_id"));var target=contract(id(q,"target_contract_id"));rooms.access(p,id(target,"property_id"));if(!"TERMINATED".equals(old.get("status"))||target.get("operational_ended_at")!=null||!Set.of("ACTIVE","EXPIRING").contains(target.get("status"))||rows("SELECT id FROM rental_checkins WHERE contract_id=:id AND status='COMPLETED'",id(target,"id")).isEmpty())throw fail("TRANSFER_STEPS_INCOMPLETE","Cần đóng tài chính hợp đồng cũ và nhận phòng mới thực tế trước hoàn tất.");db.sql("UPDATE contract_change_requests SET status='COMPLETED',version=version+1 WHERE id=:id").param("id",id).update();history(id(old,"id"),p,"TRANSFER_COMPLETED","Hợp đồng mới #"+target.get("id"));audit(id,p,"COMPLETED",r.reason());}
    @Transactional public Map<String,Object> detail(AuthenticatedUser p,long c){rooms.lockContract(c);var contract=contract(c);access(p,contract,false);return details(p,contract,rows("SELECT * FROM contract_change_requests WHERE contract_id=:id ORDER BY id DESC",c));}
    @Transactional public Map<String,Object> requestDetail(AuthenticatedUser p,long request){var q=change(p,request,false);return details(p,contract(id(q,"contract_id")),List.of(q));}
    private Map<String,Object> details(AuthenticatedUser p,Map<String,Object> c,List<Map<String,Object>> requests){var out=new LinkedHashMap<String,Object>();out.put("contract",c);out.put("requests",requests);var items=new ArrayList<Map<String,Object>>();for(var q:requests){var item=new LinkedHashMap<>(q);long id=id(q,"id");item.put("history",rows("SELECT * FROM contract_change_history WHERE request_id=:id ORDER BY id",id));item.put("confirmations",rows("SELECT * FROM contract_change_confirmations WHERE request_id=:id ORDER BY id",id));boolean staff=Set.of(RoleCode.OWNER,RoleCode.MANAGER).contains(p.activeRole());String status=q.get("status").toString();item.put("canOffer",staff&&status.equals("REQUESTED"));item.put("canConfirm",p.activeRole()==RoleCode.TENANT&&status.equals("OFFERED"));item.put("canApply",staff&&status.equals("AGREED"));item.put("canCancel",Set.of("REQUESTED","OFFERED","AGREED","PREPARED").contains(status));item.put("canComplete",staff&&status.equals("PREPARED"));items.add(item);}out.put("requests",items);
        out.put("canRequest",(p.activeRole()!=RoleCode.TENANT||p.id()==id(c,"tenant_id"))&&Set.of("ACTIVE","EXPIRING","EXPIRED").contains(c.get("status"))&&requests.stream().noneMatch(x->Set.of("REQUESTED","OFFERED","AGREED","PREPARED").contains(x.get("status"))));
        out.put("rooms",db.sql("SELECT r.id,r.code,p.name property_name,r.capacity,r.property_id FROM rooms r JOIN properties p ON p.id=r.property_id WHERE p.owner_id=:owner AND (:manager=0 OR EXISTS(SELECT 1 FROM property_managers m WHERE m.property_id=p.id AND m.manager_id=:actor)) AND r.status IN ('READY','VACANT') AND p.status='ACTIVE' AND NOT EXISTS(SELECT 1 FROM contracts c WHERE c.room_id=r.id AND c.status IN ('PENDING_CONFIRMATION','ACTIVE','EXPIRING','EXPIRED','SETTLING','TERMINATION_REQUESTED') AND c.operational_ended_at IS NULL) ORDER BY p.id,r.code").param("owner",c.get("owner_id")).param("manager",p.activeRole()==RoleCode.MANAGER?1:0).param("actor",p.id()).query().listOfRows());out.put("residents",rows("SELECT tr.id,tr.tenant_profile_id,tr.residence_role,tr.move_in_date,tr.move_out_date,tr.status,tp.full_name,tp.user_id FROM tenant_residences tr JOIN tenant_profiles tp ON tp.id=tr.tenant_profile_id WHERE tr.contract_id=:id ORDER BY tr.id",id(c,"id")));out.put("prices",rows("SELECT * FROM billing_rate_versions WHERE contract_id=:id AND code='RENT' ORDER BY effective_date,id",id(c,"id")));return invitationView(p,c,out);}
}
